    List<ThreadSnapshot> result = new java.util.ArrayList<>();
    try (java.io.BufferedReader reader = java.nio.file.Files.newBufferedReader(file.toPath())) {
        String line;
        while ((line = reader.readLine()) != null) {
            // Assuming ThreadSnapshot has a constructor that takes a single line of data
            ThreadSnapshot snapshot = new ThreadSnapshot(line);
            long tsTime = snapshot.getTimestamp(); // assuming a method that returns the snapshot timestamp
            for (ProfileAnalyzeTimeRange range : timeRanges) {
                if (tsTime >= range.getStartTime() && tsTime <= range.getEndTime()) {
                    result.add(snapshot);
                    break;
                }
            }
        }
    }
    return result;
}
